import{_ as t,o as h,c as i,a3 as o}from"./chunks/framework.DX_KL3e0.js";const a="/help/guide/install-android.svg",g="/help/guide/install-ios.svg",p=JSON.parse('{"title":"Dùng trên điện thoại & Cài đặt ứng dụng","description":"","frontmatter":{},"headers":[],"relativePath":"bat-dau/dien-thoai.md","filePath":"bat-dau/dien-thoai.md","lastUpdated":1782144415000}'),r={name:"bat-dau/dien-thoai.md"};function s(c,n,d,e,l,u){return h(),i("div",null,[...n[0]||(n[0]=[o('<h1 id="dung-tren-đien-thoai-cai-đat-ung-dung" tabindex="-1">Dùng trên điện thoại &amp; Cài đặt ứng dụng <a class="header-anchor" href="#dung-tren-đien-thoai-cai-đat-ung-dung" aria-label="Permalink to &quot;Dùng trên điện thoại &amp; Cài đặt ứng dụng&quot;">​</a></h1><p>FADO AssetFlow hoạt động mượt trên điện thoại như một <strong>ứng dụng thật</strong>: có thanh điều hướng dưới đáy kiểu app, và bạn có thể <strong>cài thẳng lên màn hình chính</strong> (Android &amp; iPhone/iPad) để mở nhanh, chạy toàn màn hình, không cần gõ địa chỉ web mỗi lần.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Giao diện điện thoại:</strong> thanh tab dưới đáy 5 mục, đổi theo vai trò; mọi chức năng khác nằm trong tab <strong>Menu</strong>.</li><li><strong>Cài như app:</strong> mở <code>https://assetflow.fadoai.com</code> bằng trình duyệt → <strong>Thêm vào Màn hình chính</strong>.</li><li><strong>Android:</strong> dùng Chrome. <strong>iPhone/iPad:</strong> dùng <strong>Safari</strong>.</li><li>Sau khi cài: có <strong>biểu tượng riêng</strong>, mở <strong>toàn màn hình</strong>, chạy y như một ứng dụng.</li></ul></div><h2 id="_1-giao-dien-tren-đien-thoai" tabindex="-1">1. Giao diện trên điện thoại <a class="header-anchor" href="#_1-giao-dien-tren-đien-thoai" aria-label="Permalink to &quot;1. Giao diện trên điện thoại&quot;">​</a></h2><p>Khi mở trên màn hình nhỏ, bố cục tự chuyển sang chế độ điện thoại:</p><ul><li><strong>Thanh tab dưới đáy</strong> thay cho sidebar — luôn nằm trong tầm ngón tay cái.</li><li><strong>Tiêu đề trang gọn</strong> ở trên cùng, các trang xếp thành <strong>1 cột</strong> để dễ thao tác.</li><li>Nhiều thao tác (tạo mới, lọc, chi tiết) mở dạng <strong>bảng trượt từ dưới lên</strong> (bottom sheet) thay vì hộp thoại giữa màn hình.</li></ul><div class="info custom-block"><p class="custom-block-title">📸 Ảnh minh họa</p><p>Màn hình điện thoại với thanh tab dưới đáy. <em>(Ảnh sẽ được bổ sung.)</em></p></div><h3 id="thanh-tab-duoi-đay" tabindex="-1">Thanh tab dưới đáy <a class="header-anchor" href="#thanh-tab-duoi-đay" aria-label="Permalink to &quot;Thanh tab dưới đáy&quot;">​</a></h3><p>Gồm <strong>5 mục cố định</strong>, trong đó mục thứ ba thay đổi theo vai trò của bạn:</p><table tabindex="0"><thead><tr><th>Tab</th><th style="text-align:center;">Biểu tượng</th><th>Mở đến</th><th>Hiển thị cho</th></tr></thead><tbody><tr><td><strong>Trang chủ</strong></td><td style="text-align:center;">🏠</td><td>Dashboard</td><td>Mọi người</td></tr><tr><td><strong>Chấm công</strong></td><td style="text-align:center;">🫆</td><td>Dữ liệu chấm công của tôi</td><td>Mọi người</td></tr><tr><td><strong>Duyệt</strong></td><td style="text-align:center;">☑️</td><td>Duyệt yêu cầu</td><td>Quản lý · Admin · Super Admin</td></tr><tr><td><strong>Công việc</strong></td><td style="text-align:center;">📋</td><td>Công việc của tôi</td><td>Người dùng cuối</td></tr><tr><td><strong>Menu</strong></td><td style="text-align:center;">▦</td><td>Tất cả chức năng còn lại</td><td>Mọi người</td></tr><tr><td><strong>Tài khoản</strong></td><td style="text-align:center;">👤</td><td>Hồ sơ &amp; đăng xuất</td><td>Mọi người</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Mục thứ ba đổi theo vai trò</p><p>Nếu bạn là <strong>Quản lý/Admin</strong>, tab thứ ba là <strong>Duyệt</strong> (yêu cầu chờ duyệt). Nếu là <strong>Người dùng cuối</strong>, tab đó là <strong>Công việc</strong>. Bạn sẽ chỉ thấy đúng tab phù hợp với mình.</p></div><h3 id="tab-menu-—-cua-vao-moi-chuc-nang" tabindex="-1">Tab &quot;Menu&quot; — cửa vào mọi chức năng <a class="header-anchor" href="#tab-menu-—-cua-vao-moi-chuc-nang" aria-label="Permalink to &quot;Tab &quot;Menu&quot; — cửa vào mọi chức năng&quot;">​</a></h3><p>Thanh dưới đáy chỉ để 4 lối tắt hay dùng nhất. <strong>Mọi module khác</strong> (Tài sản, Tổ chức, Ticket, Đặt phòng họp, Nhân sự, Tra cứu, Cài đặt…) nằm gọn trong tab <strong>Menu</strong> — và vẫn <strong>lọc theo quyền</strong>: bạn chỉ thấy những gì mình được phép truy cập (giống sidebar trên máy tính).</p><h3 id="tab-tai-khoan" tabindex="-1">Tab &quot;Tài khoản&quot; <a class="header-anchor" href="#tab-tai-khoan" aria-label="Permalink to &quot;Tab &quot;Tài khoản&quot;&quot;">​</a></h3><p>Mở hồ sơ cá nhân, chuyển công ty (nếu bạn thuộc nhiều công ty), và <strong>đăng xuất</strong>.</p><div class="info custom-block"><p class="custom-block-title">Trên máy tính thì sao?</p><p>Trên màn hình lớn, giao diện vẫn dùng <strong>sidebar bên trái + topbar</strong> như cũ — xem <a href="/help/bat-dau/giao-dien-chung.html">Giao diện chung</a>. Thanh tab dưới đáy chỉ xuất hiện ở điện thoại/màn hình nhỏ.</p></div><h2 id="_2-cai-đat-len-man-hinh-chinh-nhu-mot-app" tabindex="-1">2. Cài đặt lên màn hình chính (như một app) <a class="header-anchor" href="#_2-cai-đat-len-man-hinh-chinh-nhu-mot-app" aria-label="Permalink to &quot;2. Cài đặt lên màn hình chính (như một app)&quot;">​</a></h2><p>Cài đặt giúp FADO AssetFlow có <strong>biểu tượng riêng</strong> trên màn hình chính, mở <strong>toàn màn hình</strong> (không có thanh địa chỉ trình duyệt), khởi động nhanh như ứng dụng tải từ cửa hàng — nhưng <strong>không tốn dung lượng cài đặt</strong> và <strong>luôn là phiên bản mới nhất</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Không cần ra App Store / CH Play</p><p>FADO AssetFlow là <strong>ứng dụng web cài được (PWA)</strong>. Bạn cài trực tiếp từ trình duyệt, không qua App Store hay CH Play.</p></div><h3 id="📱-android-chrome" tabindex="-1">📱 Android (Chrome) <a class="header-anchor" href="#📱-android-chrome" aria-label="Permalink to &quot;📱 Android (Chrome)&quot;">​</a></h3><p><img src="'+a+'" alt="Hướng dẫn cài trên Android (Chrome) — 3 bước"></p><ol><li>Mở <strong>Chrome</strong>, vào <code>https://assetflow.fadoai.com</code> và <strong>đăng nhập</strong>.</li><li>Nhấn nút <strong>⋮</strong> (ba chấm) ở góc trên bên phải.</li><li>Chọn <strong>&quot;Thêm vào Màn hình chính&quot;</strong> (hoặc <strong>&quot;Cài đặt ứng dụng&quot;</strong>).</li><li>Xác nhận tên → nhấn <strong>Thêm / Cài đặt</strong>.</li><li>Biểu tượng <strong>AssetFlow</strong> xuất hiện trên màn hình chính — mở lên là dùng ngay.</li></ol><div class="info custom-block"><p class="custom-block-title">Có thể hiện sẵn dải mời cài</p><p>Đôi khi Chrome tự hiện dải <strong>&quot;Thêm AssetFlow vào màn hình chính&quot;</strong> ở dưới — chỉ cần nhấn vào đó là xong.</p></div><blockquote><p>Trình duyệt <strong>Samsung Internet</strong> cũng hỗ trợ: nhấn ☰ → <strong>Thêm trang vào</strong> → <strong>Màn hình chính</strong>.</p></blockquote><h3 id="🍎-iphone-ipad-safari" tabindex="-1">🍎 iPhone / iPad (Safari) <a class="header-anchor" href="#🍎-iphone-ipad-safari" aria-label="Permalink to &quot;🍎 iPhone / iPad (Safari)&quot;">​</a></h3><p><img src="'+g+'" alt="Hướng dẫn cài trên iPhone/iPad (Safari) — 3 bước"></p><div class="warning custom-block"><p class="custom-block-title">Phải dùng Safari</p><p>Trên iPhone/iPad, hãy mở bằng <strong>Safari</strong>. Tính năng &quot;Thêm vào Màn hình chính&quot; cho ứng dụng web hoạt động đầy đủ nhất trên Safari.</p></div><ol><li>Mở <strong>Safari</strong>, vào <code>https://assetflow.fadoai.com</code> và <strong>đăng nhập</strong>.</li><li>Nhấn nút <strong>Chia sẻ</strong> (hình ô vuông có mũi tên hướng lên) ở thanh dưới (hoặc trên cùng).</li><li>Vuốt xuống, chọn <strong>&quot;Thêm vào MH chính&quot;</strong> <em>(Add to Home Screen)</em>.</li><li>Sửa tên nếu muốn → nhấn <strong>Thêm</strong>.</li><li>Biểu tượng <strong>AssetFlow</strong> xuất hiện trên màn hình chính.</li></ol><h3 id="sau-khi-cai" tabindex="-1">Sau khi cài <a class="header-anchor" href="#sau-khi-cai" aria-label="Permalink to &quot;Sau khi cài&quot;">​</a></h3><ul><li>Mở app từ biểu tượng → chạy <strong>toàn màn hình</strong>, không có thanh địa chỉ.</li><li>Đăng nhập một lần, lần sau mở lại thường <strong>không phải đăng nhập lại</strong> (trừ khi bạn đăng xuất hoặc phiên hết hạn).</li><li>Muốn <strong>gỡ</strong>: nhấn giữ biểu tượng → <strong>Gỡ cài đặt / Xóa ứng dụng</strong> (giống mọi app khác).</li></ul><h2 id="_3-cau-hoi-thuong-gap" tabindex="-1">3. Câu hỏi thường gặp <a class="header-anchor" href="#_3-cau-hoi-thuong-gap" aria-label="Permalink to &quot;3. Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Cài app này có tốn phí hay tốn dung lượng không?</strong> Không tốn phí. Dung lượng chiếm rất nhỏ vì nội dung tải khi cần; bạn luôn dùng bản mới nhất mà không phải cập nhật thủ công.</p><p><strong>Tôi không thấy mục &quot;Thêm vào Màn hình chính&quot;?</strong></p><ul><li>Android: đảm bảo đang dùng <strong>Chrome</strong> (không phải trình duyệt trong ứng dụng Facebook/Zalo). Mở bằng Chrome rồi thử lại.</li><li>iPhone/iPad: đảm bảo đang dùng <strong>Safari</strong>, không phải Chrome hay trình duyệt khác.</li></ul><p><strong>Mở app nhưng bị hỏi đăng nhập lại?</strong> Phiên đăng nhập có thể đã hết hạn, hoặc bạn đã đăng xuất trước đó. Đăng nhập lại bình thường. Xem thêm <a href="/help/bat-dau/dang-nhap.html">Đăng nhập &amp; đăng xuất</a>.</p><p><strong>Có thông báo đẩy (push) như app cửa hàng không?</strong> Thông báo hệ thống hiển thị qua <strong>chuông thông báo</strong> trong app và qua <strong>Telegram</strong> nếu bạn đã liên kết. Đây là kênh nhắc việc chính trên điện thoại.</p><p><strong>Dùng được trên máy tính bảng không?</strong> Được. iPad cài qua Safari, máy tính bảng Android cài qua Chrome — cách làm như trên.</p><hr><p><em>Liên quan:</em> <a href="/help/bat-dau/giao-dien-chung.html">Giao diện chung</a> · <a href="/help/bat-dau/dang-nhap.html">Đăng nhập</a></p>',39)])])}const b=t(r,[["render",s]]);export{p as __pageData,b as default};
